head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[xml > M > getChildren]<br/>XPath 로 검색한 노드의 하위 Element 노드들을 태그명과 속성 정보가 담긴 객체 배열로 반환합니다.",
    "validation" : [
        "doc(필수) 파라미터로 Element 노드를 설정할 수 있어야 합니다.",
    ]
}

scwin.testDoc = null;
scwin.bookNode = null;

scwin.onpageload = function () {
    $c.gcm.createCommonDatalist();
    wf_body_left.getObj("scwin").createValidation(scwin.tData);

    scwin.testDoc = WebSquare.xml.parse(
        "<bookstore>" +
            "<book id='b1' category='fiction'>" +
                "<title lang='eng'>Harry Potter</title>" +
                "<author country='UK'>J.K. Rowling</author>" +
                "<price currency='USD'>29.99</price>" +
            "</book>" +
            "<book id='b2' category='tech'>" +
                "<title lang='eng'>Learning XML</title>" +
                "<price currency='KRW'>39000</price>" +
            "</book>" +
        "</bookstore>"
    );
};



scwin.btn_getChildren_onclick = function () {
    let docIndex = par_doc.getValue();

    var bookNodes = scwin.testDoc.getElementsByTagName("book");
    var targetBook = bookNodes[Number(docIndex)];

    var result = WebSquare.xml.getChildren(targetBook, ".");

    wf_body_bottom.getObj("scwin").setReturnValue("Element 기준 : book[" + docIndex + "] 내에서 getChildren('.')");
    wf_body_bottom.getObj("scwin").setReturnValue("결과 개수 : " + result.length);

    for (var i = 0; i < result.length; i++) {
        wf_body_bottom.getObj("scwin").setReturnValue("[" + i + "] " + JSON.stringify(result[i]));
    }
}
